-- Fictional, date-relative portfolio data. Safe to re-run.
select 'CMP-' || lpad(n::text,3,'0'),'Standard hardware component ' || n,(array['SUP-ORBIT','SUP-NOVA','SUP-HELIX','SUP-VOLT','SUP-AXIS','SUP-PRECISION','SUP-PULSE','SUP-KINETIC'])[1 + ((n - 1) % 8)],12 + ((n % 6) * 7),30 + (n * 5),20 from generate_series(1,20) as n
on conflict(code) do update set on_hand=excluded.on_hand;
